// One item per keyword. One keyword per line (commas and semicolons also separate).
const MAX = 10; // SerpApi free tier: 50 searches/hour, 250/month
const form = $input.first().json;
// Only the form's three marketplaces. A tampered value (n8n doesn't check dropdowns on the server) would be searched,
// scored as US dollars or crash the run, so anything else counts as amazon.com.
const marketplace = (['amazon.com', 'amazon.co.uk', 'amazon.ca'].includes(form.Marketplace) ? form.Marketplace : 'amazon.com');

const seen = new Set();
const list = [];
const junk = [];
for (const part of String(form.Keywords || '').split(/[\n,;]+/)) {
  const k = part.toLowerCase()
    .replace(/\s+/g, ' ')
    .trim()
    .replace(/^[^a-z0-9]+|[^a-z0-9]+$/g, ''); // strip punctuation at the ends: "rubber bands!!!" -> "rubber bands"
  if (!k) {
    if (part.trim()) junk.push(part.trim()); // something was typed, but no letters or digits
    continue;
  }
  if (seen.has(k)) continue;
  seen.add(k);
  list.push(k);
}
if (list.length === 0) {
  throw new Error(`No keywords entered.${junk.length ? ` Ignored ${junk.join(' ')} because it has no letters or digits.` : ''}`);
}

const kept = list.slice(0, MAX);
const dropped = list.slice(MAX);
const batchId = $now.toFormat('yyyy-MM-dd HH:mm:ss') + ' PKT';

return kept.map((keyword, i) => ({
  json: {
    batch_id: batchId,
    order: i + 1,
    keyword,
    marketplace,
    dropped: dropped.join(', '),
  },
}));

// Bundle everything the core needs into ONE item: each keyword with its raw search, plus the saved history.
// Search results line up with Split Keywords by position (one search per keyword, failures included).
const requests = $('Split Keywords').all().map(i => i.json);
const responses = $('Search Amazon (SerpApi)').all().map(i => i.json);
const history = $('Read History').all().map(i => i.json).filter(r => r.run_id);
return [{
  json: {
    tool: 'i1',
    batch_id: requests[0].batch_id,
    searches: requests.map((req, idx) => ({ order: req.order, keyword: req.keyword, marketplace: req.marketplace, response: responses[idx] ?? { error: 'no response' } })),
    history,
    dropped: (requests[0].dropped || '').split(', ').filter(Boolean),
  },
}];

// ---- Result page: shared design (Amazon Toolkit). Presentation only: every value is copied from earlier nodes. ----
const esc = t => String(t ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const CURS = { 'amazon.com': '$', 'amazon.co.uk': '£', 'amazon.ca': 'C$' };
const num = v => (v === '' || v === null || v === undefined || Number.isNaN(Number(v)) ? null : Number(v));
const int = v => (num(v) === null ? '–' : Math.round(num(v)).toLocaleString('en-US'));
const money = (v, cur) => (num(v) === null ? '–' : `${cur}${num(v).toFixed(2)}`);
const big = (v, cur = '') => { const n = num(v); if (n === null) return '–'; if (n >= 1e6) return `${cur}${(n / 1e6).toFixed(2)}M`; if (n >= 1e4) return `${cur}${Math.round(n / 1e3)}K`; return `${cur}${int(n)}`; };
const rating = v => (num(v) === null ? '–' : num(v).toFixed(1));
const spots = t => esc(String(t ?? '').split(' | ').join(' · '));
const split = t => String(t ?? '').split(' | ').map(s => s.trim()).filter(Boolean);
const LEVEL = { high: 'yes', medium: 'mid', low: 'no' };
const pill = (text, kind) => `<span class="pill ${kind || ''}">${esc(text)}</span>`;
const levelPill = t => pill(t, LEVEL[String(t || '').toLowerCase()] || 'muted');
const tiles = list => `<div class="tiles">${list.map(([v, l]) => `<div class="tile"><div class="tv">${v}</div><div class="tl">${esc(l)}</div></div>`).join('')}</div>`;
const section = (title, body) => (body ? `<section><h2>${esc(title)}</h2>${body}</section>` : '');
const table = (head, rows, right = []) => `<div class="tw"><table><thead><tr>${head.map((h, i) => `<th${right.includes(i) ? ' class="r"' : ''}>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(r => `<tr>${r.map((c, i) => `<td${right.includes(i) ? ' class="r"' : ''}>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
const notesList = list => (list.length ? `<ul class="notes">${list.map(n => `<li>${esc(n)}</li>`).join('')}</ul>` : '');
const chips = list => (list.length ? `<div class="chips">${list.map(c => `<span class="chip">${esc(c)}</span>`).join('')}</div>` : '');

function page({ code, tool, colour, tint, title, meta, verdict, body, saved, cannotTell }) {
  // Charcoal design: charcoal room, crimson brand band, ivory summary card, tool colour on the kicker and accents.
  // colour and tint from the call are kept for the record; the look comes from THEME.
  const THEME = {
    i1: { c: '#D77343', d: '#A8441F', k: 'Market scores' },
    i2: { c: '#E8DCCB', d: '#A11F38', k: 'Buyer complaints' },
    i3: { c: '#679DD4', d: '#3F64A6', k: 'Weak competitors' },
    i4: { c: '#DAAC53', d: '#7A5A14', k: 'Full run' },
    i5: { c: '#9485D0', d: '#5F59A8', k: 'Keyword ideas' },
  };
  const t = THEME[code] || THEME.i1;
  const num2 = String(code).replace(/[^0-9]/g, '').padStart(2, '0');
  const mark = `<svg width="22" height="29" viewBox="0 0 26 34" aria-hidden="true"><path d="M13 1 L25 9 L25 31 Q25 33 23 33 L3 33 Q1 33 1 31 L1 9 Z" fill="#F2EADD"/><circle cx="13" cy="9" r="3" fill="#8F8AD0"/></svg>`;
  return `<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>${esc(tool)} · ${esc(title)}</title>
<style>
@import url('https://fonts.googleapis.com/css2?family=Bricolage+Grotesque:opsz,wght@12..96,600;12..96,700;12..96,800&family=Newsreader:opsz,wght@6..72,400;6..72,500&family=Instrument+Sans:wght@400;500;600&display=swap');
