/* The form: a plain ivory card */
form.card { grid-area: form; grid-row: 2 / span 3; margin: 128px 0 0; padding: 40px 36px 36px !important; border: 1px solid #E2D7C6 !important; border-radius: 12px; background: #F2EADD; box-shadow: none; }
.form-header::before { content: 'Tool 01  ·  Market scores'; display: block; margin-bottom: 12px; font: 600 12px/1 'Instrument Sans', system-ui, sans-serif; letter-spacing: 1.6px; text-transform: uppercase; color: #A8441F; }
.form-header h1 { font: 700 32px/1.1 'Bricolage Grotesque', system-ui, sans-serif; letter-spacing: -0.5px; text-align: left; margin: 0; color: #2A0E16; }
.form-header p { font: 400 16px/1.55 'Newsreader', Georgia, serif; color: #5A4A55; text-align: left; padding-top: 10px; margin: 0; }
.inputs-wrapper { padding-top: 26px; padding-bottom: 4px; }
form label { font: 600 15px/20px 'Bricolage Grotesque', system-ui, sans-serif; color: #2A0E16; padding-bottom: 8px; }
form .form-input, form select { padding: 12px 14px; line-height: 24px; }
form textarea { min-height: 112px; }
form textarea, form .form-input, form select, form select option { font-family: 'Newsreader', Georgia, serif; font-size: 17px; }
form select, form .select-input, form .form-input { background-color: #FFFBF4; color: #2A0E16; }
form .form-input::placeholder { color: #9C8F80; }
.error-hidden { visibility: hidden; }
form .form-input:focus, .select-input:focus-within { box-shadow: 0 0 0 3px rgba(215,115,67,0.3); }
#submit-btn { font: 700 17px 'Bricolage Grotesque', system-ui, sans-serif; color: #F2EADD; border-radius: 6px; }
#submit-btn:hover { filter: brightness(1.07); }
#submit-btn:focus-visible { outline: 3px solid #F2EADD; outline-offset: 3px; }
/* Search cost: the n8n credit line becomes a small crimson pill in the card's corner */
.n8n-link {
  grid-area: form; grid-row: 2; justify-self: end; align-self: start; position: relative; z-index: 3; pointer-events: none;
  margin: 150px 36px 0 0; padding: 5px 12px; border-radius: 999px; background: #930031;
  display: flex; gap: 6px; align-items: baseline; font-size: 0;
}
.n8n-link a { display: none; }
.n8n-link::before { content: '1 per'; white-space: nowrap; font: 800 13px/1 'Bricolage Grotesque', system-ui, sans-serif; color: #F2EADD; }
.n8n-link::after { content: 'keyword'; white-space: nowrap; font: 600 10px/1 'Instrument Sans', system-ui, sans-serif; letter-spacing: 1px; text-transform: uppercase; color: #F4C6D1; }
hr { display: none; }
.test-notice { grid-column: 1 / -1; }
/* Phones and small tablets */
@media (max-width: 960px) {
  .container { max-width: 560px; padding: 0 20px 48px; grid-template-columns: minmax(0, 1fr); grid-template-areas: "brand" "head" "copy" "form"; grid-template-rows: none; }
  .container::before { margin: 0 -20px; padding-left: 64px; background-position: 20px center, 0 0; }
  section::before { font-size: 38px; margin-top: 36px; }
  section::after { font-size: 16px; padding-bottom: 0; background: none; }
  form.card { grid-row: 4; margin-top: 28px; padding: 30px 22px 26px !important; }
  .form-header::before { padding-right: 130px; line-height: 1.4; }
  .n8n-link { grid-row: 4; margin: 50px 22px 0 0; }
  :root { --padding-card: 22px; }
}
